// Mirage POSIX <time.h> per-process timers — timer_create / timer_settime /
// timer_gettime / timer_delete / timer_getoverrun.
//
// Spec sources
// ------------
//   * IEEE Std 1003.1-2017 §<time.h>:
//       int timer_create(clockid_t clock_id, struct sigevent *evp,
//                        timer_t *timerid);
//       int timer_settime(timer_t timerid, int flags,
//                         const struct itimerspec *value,
//                         struct itimerspec *ovalue);
//       int timer_gettime(timer_t timerid, struct itimerspec *value);
//       int timer_getoverrun(timer_t timerid);
//       int timer_delete(timer_t timerid);
//
//   * struct itimerspec — { struct timespec it_interval, it_value }.
//   * struct sigevent — { int sigev_notify, int sigev_signo,
//                         union sigval sigev_value, function *sigev_notify_function,
//                         pthread_attr_t *sigev_notify_attributes }.
//     sigev_notify ∈ { SIGEV_NONE, SIGEV_SIGNAL, SIGEV_THREAD, SIGEV_THREAD_ID }.
//   * TIMER_ABSTIME flag for timer_settime — the value is interpreted as an
//     absolute time on the timer's clock instead of a relative duration.
//   * Per POSIX: "If the time period of a timer expires while a signal
//     generated by the same timer is still pending, the count of timer
//     expirations is incremented" — this is the "overrun" counter, queried
//     via timer_getoverrun.
//
// Implementation
// --------------
// Each timer is backed by a Node.js setTimeout (initial fire) plus, if
// it_interval > 0, a setInterval (periodic fires).  On each fire we:
//
//   * If sigev_notify == SIGEV_SIGNAL — raise the configured RT signal at
//     the registered owner thread via the concurrency subproject's
//     pthread_kill_async (which routes through the SAB-backed RT FIFO and
//     wakes any sigwait/Atomics.wait sleeper).  The sigval is delivered as
//     part of the siginfo_t, matching the POSIX queued-RT-signal contract.
//   * If sigev_notify == SIGEV_THREAD — invoke the user-supplied
//     notification function asynchronously.
//   * If sigev_notify == SIGEV_NONE — only update internal state; the timer
//     is observable only via timer_gettime.
//
// The overrun counter increments every time the timer would have fired but
// the previous notification was still pending (we approximate this as "fires
// queued faster than the dispatcher consumed them").  Since the concurrency
// subproject's RT signal queue can hold SIGQUEUE_MAX entries (default 32),
// only enqueueing failures count as overruns — that matches the spirit of
// POSIX §timer_getoverrun: "the difference between the number of expirations
// that have occurred and the number of those expirations that have been
// reported".
//
// BRIDGE: posix-timer — POSIX per-process timers → Node.js setTimeout/
// setInterval + concurrency.signal-delivery.pthread_kill_async; timer_t is a
// numeric handle into a per-process registry.

// ---------------------------------------------------------------------------
// errno values (POSIX <errno.h>).
// ---------------------------------------------------------------------------
const EINVAL = 22;
const EAGAIN = 11;

/** Module-level errno — POSIX §2.3. */
export let errno: number = 0;

// ---------------------------------------------------------------------------
// Constants — POSIX §<time.h> + Linux extensions.
// ---------------------------------------------------------------------------

export const CLOCK_REALTIME            = 0;
export const CLOCK_MONOTONIC           = 1;
export const CLOCK_PROCESS_CPUTIME_ID  = 2;
export const CLOCK_THREAD_CPUTIME_ID   = 3;
export const CLOCK_MONOTONIC_RAW       = 4;
export const CLOCK_REALTIME_COARSE     = 5;
export const CLOCK_MONOTONIC_COARSE    = 6;
export const CLOCK_BOOTTIME            = 7;

/** sigev_notify values — POSIX §<signal.h>. */
export const SIGEV_NONE      = 1;
export const SIGEV_SIGNAL    = 0;
export const SIGEV_THREAD    = 2;
export const SIGEV_THREAD_ID = 4;

/** timer_settime flags — POSIX §<time.h>. */
export const TIMER_ABSTIME = 1;

// ---------------------------------------------------------------------------
// Types.
// ---------------------------------------------------------------------------

/** struct timespec — POSIX §<time.h>. */
export interface timespec {
  tv_sec:  number;
  tv_nsec: number;
}

/** struct itimerspec — POSIX §<time.h>. */
export interface itimerspec {
  it_interval: timespec;
  it_value:    timespec;
}

/** union sigval — POSIX §<signal.h>. */
export interface sigval {
  sival_int: number;
  sival_ptr: any;
}

/** struct sigevent — POSIX §<signal.h>. */
export interface sigevent {
  sigev_notify: number;
  sigev_signo:  number;
  sigev_value:  sigval;
  sigev_notify_function?: ((sv: sigval) => void) | null;
  sigev_notify_attributes?: any;
  /** Linux: target thread id for SIGEV_THREAD_ID. */
  sigev_notify_thread_id?: number;
}

/** timer_t — opaque numeric handle.  Translated code stores it in an
 *  out-pointer { value: number }. */
export type timer_t = number;

// ---------------------------------------------------------------------------
// Per-timer state.
// ---------------------------------------------------------------------------

interface TimerState {
  id: timer_t;
  clockid: number;
  evp: sigevent;
  spec: itimerspec;
  /** Active Node setTimeout / setInterval handles. */
  initialHandle: any;
  intervalHandle: any;
  /** Wall-clock ms timestamp of the last arming (for timer_gettime). */
  armedAt: number;
  /** POSIX timer_getoverrun counter — fires that the dispatcher could not
   *  enqueue (signal queue full, or handler not yet returned). */
  overrun: number;
  /** Owning thread id — defaults to the creating-thread tid; SIGEV_THREAD_ID
   *  overrides. */
  ownerTid: number;
}

const _table: Map<timer_t, TimerState> = new Map();
let _nextId: timer_t = 1;

/** Test inspector — number of live timers. */
export function _timerCount(): number { return _table.size; }

/** Test inspector — peek a timer's spec without altering it. */
export function _timerSpec(id: timer_t): itimerspec | null {
  const st = _table.get(id);
  return st ? {
    it_interval: { ...st.spec.it_interval },
    it_value:    { ...st.spec.it_value },
  } : null;
}

/** Test-only — drop every timer + reset id allocator. */
export function _resetPosixTimer(): void {
  for (const st of _table.values()) {
    if (st.initialHandle  !== null) { try { clearTimeout(st.initialHandle); } catch { /* noop */ } }
    if (st.intervalHandle !== null) { try { clearInterval(st.intervalHandle); } catch { /* noop */ } }
  }
  _table.clear();
  _nextId = 1;
  errno = 0;
  _api = undefined;
}

// ---------------------------------------------------------------------------
// Lazy resolution of the concurrency signal-delivery API.  We don't take a
// hard dependency because translated Mirage-only programs may not load the
// full concurrency runtime.  When unavailable, SIGEV_SIGNAL is approximated
// by invoking the registered sigaction handler directly (best-effort).
// ---------------------------------------------------------------------------

interface SignalDeliveryAPI {
  pthread_kill_async: (target_tid: number, sig: number, sigval?: number) => number;
  signal_current_tid: () => number;
  sigaction_get?: (sig: number) => any;
  __cpp_pthread_signal_dispatch_check?: () => number;
}

let _api: SignalDeliveryAPI | null | undefined;

/** Test-only — install a custom signal-delivery API. */
export function _setSignalDeliveryAPI(api: SignalDeliveryAPI | null): void {
  _api = api;
}

async function _resolveAPI(): Promise<SignalDeliveryAPI | null> {
  if (_api !== undefined) return _api;
  try {
    const modName = "concurrency/dist/signal-delivery.js";
    const mod: any = await (Function("m", "return import(m)") as any)(modName);
    _api = {
      pthread_kill_async: mod.pthread_kill_async,
      signal_current_tid: mod.signal_current_tid,
      sigaction_get: mod.sigaction_get,
      __cpp_pthread_signal_dispatch_check: mod.__cpp_pthread_signal_dispatch_check,
    };
  } catch { _api = null; }
  return _api;
}

// Synchronous best-effort accessor — many timer fires happen on the Node
// event loop and want to deliver immediately.
function _apiSync(): SignalDeliveryAPI | null {
  return _api === undefined || _api === null ? null : _api;
}

// ---------------------------------------------------------------------------
// Helpers.
// ---------------------------------------------------------------------------

function _tsToMs(ts: timespec): number {
  return ts.tv_sec * 1000 + ts.tv_nsec / 1_000_000;
}

function _msToTs(ms: number): timespec {
  const sec = Math.floor(ms / 1000);
  const nsec = Math.floor((ms - sec * 1000) * 1_000_000);
  return { tv_sec: sec, tv_nsec: nsec };
}

function _disarm(st: TimerState): void {
  if (st.initialHandle !== null) {
    try { clearTimeout(st.initialHandle); } catch { /* noop */ }
    st.initialHandle = null;
  }
  if (st.intervalHandle !== null) {
    try { clearInterval(st.intervalHandle); } catch { /* noop */ }
    st.intervalHandle = null;
  }
}

function _fire(st: TimerState): void {
  switch (st.evp.sigev_notify) {
    case SIGEV_NONE:
      // No notification — just update state.
      break;
    case SIGEV_SIGNAL:
    case SIGEV_THREAD_ID: {
      const api = _apiSync();
      if (api) {
        const r = api.pthread_kill_async(st.ownerTid, st.evp.sigev_signo,
                                         st.evp.sigev_value.sival_int);
        if (r !== 0) {
          // Could not enqueue — count an overrun per POSIX
          // §timer_getoverrun.
          st.overrun++;
        } else {
          // Drive the dispatcher so the registered sigaction handler
          // observes the signal.  In the cooperative model we have to
          // poke the dispatcher; pthread_kill_async only enqueues.
          try { api.__cpp_pthread_signal_dispatch_check?.(); } catch { /* noop */ }
        }
      } else if (st.evp.sigev_notify_function) {
        // No concurrency wired — degrade gracefully by directly invoking
        // a notification function if one is also configured.
        try { st.evp.sigev_notify_function(st.evp.sigev_value); } catch { /* noop */ }
      } else {
        // Truly nothing to do — count an overrun.
        st.overrun++;
      }
      break;
    }
    case SIGEV_THREAD: {
      // POSIX: invoke the notify function in a "new thread"; in our
      // cooperative model we schedule it on the microtask queue.
      const fn = st.evp.sigev_notify_function;
      if (fn) {
        const sv = st.evp.sigev_value;
        queueMicrotask(() => { try { fn(sv); } catch { /* noop */ } });
      } else {
        st.overrun++;
      }
      break;
    }
    default:
      // Unknown notify mode — silently ignore (POSIX-permitted).
      break;
  }
}

// ---------------------------------------------------------------------------
// timer_create — POSIX §<time.h>.
// ---------------------------------------------------------------------------

/**
 * Spec: POSIX.1-2017 §<time.h> timer_create(clock_id, evp, *timerid).
 * Allocates a new timer; writes the opaque handle through `*timerid`.  If
 * `evp` is null POSIX defaults: SIGEV_SIGNAL with SIGALRM raised against
 * the calling process.
 */
export function timer_create(
  clock_id: number,
  evp: sigevent | null,
  timerid_out: { value: timer_t } | null,
): number {
  if (!timerid_out) { errno = EINVAL; return -1; }
  if (clock_id < 0) { errno = EINVAL; return -1; }
  // Eagerly trigger the lazy resolve — fires that race with timer_create
  // are then likely to find the API ready.  We don't await the promise; the
  // module table is populated atomically in the fire path.
  void _resolveAPI();
  const tid = _apiSync()?.signal_current_tid?.() ?? 1;
  const evp2: sigevent = evp ?? {
    sigev_notify: SIGEV_SIGNAL,
    sigev_signo:  14, // SIGALRM
    sigev_value:  { sival_int: 0, sival_ptr: null },
    sigev_notify_function: null,
    sigev_notify_attributes: null,
  };
  const id: timer_t = _nextId++;
  _table.set(id, {
    id,
    clockid: clock_id,
    evp: evp2,
    spec: {
      it_interval: { tv_sec: 0, tv_nsec: 0 },
      it_value:    { tv_sec: 0, tv_nsec: 0 },
    },
    initialHandle:  null,
    intervalHandle: null,
    armedAt: 0,
    overrun: 0,
    ownerTid: evp2.sigev_notify_thread_id ?? tid,
  });
  timerid_out.value = id;
  return 0;
}

/**
 * Spec: POSIX.1-2017 §<time.h> timer_settime(id, flags, value, ovalue).
 * Arms or disarms the timer.  `flags & TIMER_ABSTIME` means `value->it_value`
 * is an absolute time on the timer's clock; otherwise it's relative.
 *
 * Returns 0 on success, -1/EINVAL on bad inputs.
 */
export function timer_settime(
  id: timer_t,
  flags: number,
  value: itimerspec | null,
  ovalue: itimerspec | null,
): number {
  const st = _table.get(id);
  if (!st) { errno = EINVAL; return -1; }
  if (!value) { errno = EINVAL; return -1; }
  // Capture old value if requested.
  if (ovalue) {
    timer_gettime(id, ovalue);
  }

  _disarm(st);
  st.spec = {
    it_interval: { tv_sec: value.it_interval.tv_sec | 0, tv_nsec: value.it_interval.tv_nsec | 0 },
    it_value:    { tv_sec: value.it_value.tv_sec    | 0, tv_nsec: value.it_value.tv_nsec    | 0 },
  };
  st.overrun = 0;

  // Disarm path: it_value == 0.
  if (st.spec.it_value.tv_sec === 0 && st.spec.it_value.tv_nsec === 0) {
    return 0;
  }

  let initialMs = _tsToMs(st.spec.it_value);
  if (flags & TIMER_ABSTIME) {
    initialMs = Math.max(0, initialMs - Date.now());
  }
  initialMs = Math.max(1, initialMs); // setTimeout floor

  st.armedAt = Date.now();
  st.initialHandle = setTimeout(() => {
    st.initialHandle = null;
    _fire(st);
    const intervalMs = _tsToMs(st.spec.it_interval);
    if (intervalMs > 0) {
      st.intervalHandle = setInterval(() => { _fire(st); }, Math.max(1, intervalMs));
      try { (st.intervalHandle as any).unref?.(); } catch { /* noop */ }
    }
  }, initialMs);
  try { (st.initialHandle as any).unref?.(); } catch { /* noop */ }
  return 0;
}

/**
 * Spec: POSIX.1-2017 §<time.h> timer_gettime(id, *value).  Writes the
 * current arming state.  it_interval is the period; it_value is the time
 * remaining until the next expiration (zero if disarmed).
 */
export function timer_gettime(id: timer_t, value: itimerspec | null): number {
  const st = _table.get(id);
  if (!st) { errno = EINVAL; return -1; }
  if (!value) { errno = EINVAL; return -1; }

  let remainingMs = 0;
  if (st.initialHandle !== null) {
    const elapsed = Date.now() - st.armedAt;
    const initialMs = _tsToMs(st.spec.it_value);
    remainingMs = Math.max(0, initialMs - elapsed);
  } else if (st.intervalHandle !== null) {
    remainingMs = _tsToMs(st.spec.it_interval);
  }

  value.it_interval = { tv_sec: st.spec.it_interval.tv_sec, tv_nsec: st.spec.it_interval.tv_nsec };
  value.it_value    = _msToTs(remainingMs);
  return 0;
}

/**
 * Spec: POSIX.1-2017 §<time.h> timer_getoverrun(id).  Returns the number of
 * extra expirations that occurred between the last delivery and the most
 * recent fire (0 means the timer fired exactly once since the last
 * delivery).
 */
export function timer_getoverrun(id: timer_t): number {
  const st = _table.get(id);
  if (!st) { errno = EINVAL; return -1; }
  return st.overrun;
}

/**
 * Spec: POSIX.1-2017 §<time.h> timer_delete(id).  Disarm and free the
 * timer.  Returns 0 on success, -1/EINVAL on unknown id.
 */
export function timer_delete(id: timer_t): number {
  const st = _table.get(id);
  if (!st) { errno = EINVAL; return -1; }
  _disarm(st);
  _table.delete(id);
  return 0;
}

// ---------------------------------------------------------------------------
// Convenience helpers — translated code commonly needs to fabricate sigevent
// / itimerspec / timespec records inline.
// ---------------------------------------------------------------------------

export function makeSigevent(opts: Partial<sigevent> = {}): sigevent {
  return {
    sigev_notify: opts.sigev_notify ?? SIGEV_SIGNAL,
    sigev_signo:  opts.sigev_signo  ?? 14,
    sigev_value:  opts.sigev_value  ?? { sival_int: 0, sival_ptr: null },
    sigev_notify_function:   opts.sigev_notify_function   ?? null,
    sigev_notify_attributes: opts.sigev_notify_attributes ?? null,
    sigev_notify_thread_id:  opts.sigev_notify_thread_id,
  };
}

export function makeItimerspec(intervalMs: number = 0, valueMs: number = 0): itimerspec {
  return {
    it_interval: _msToTs(intervalMs),
    it_value:    _msToTs(valueMs),
  };
}

// Suppress unused-warning on EAGAIN (kept exported through errno for parity).
void EAGAIN;
